from fractions import Fraction

def probability_of_winning():
    """
    Player starts at 0, needs to reach exactly 100.
    Has 2 rolls per turn, plus extra rolls for each 6 rolled.
    No snakes or ladders (pure probability).
    We calculate P(reaching 100 in one turn with 2 base rolls + bonus rolls for 6s).
    """

    # State: (position, rolls_remaining)
    # Rolling a 6 gives movement + extra roll

    # Use recursive probability with memoization
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def prob_win(position, rolls_left):
        """Probability of reaching 100 from current position with rolls_left remaining."""
        if position == 100:
            return Fraction(1, 1)
        if rolls_left == 0:
            return Fraction(0, 1)

        total_prob = Fraction(0, 1)
        for die in range(1, 7):
            new_pos = position + die
            if new_pos > 100:
                new_pos = position  # stay in place if overshoot

            if die == 6:
                # Rolling 6: move + get extra roll (rolls_left stays same effectively: use 1, gain 1)
                # So rolls_left doesn't decrease when rolling a 6
                total_prob += Fraction(1, 6) * prob_win(new_pos, rolls_left)
            else:
                total_prob += Fraction(1, 6) * prob_win(new_pos, rolls_left - 1)

        return total_prob

    # Start at position 0, with 2 rolls
    result = prob_win(0, 2)
    return result

