def find_airplane_specs(min_passengers=300):
    results = []

    seat_width = 0.45  # meters (standard economy seat)
    aisle_width = 0.5  # meters (assumed, not given)
    overhead_fraction = 0.15  # ~15% of length for cockpit/galley/lavatories

    for length in [60, 65, 70, 75, 80]:
        for width in [6, 8, 10, 12]:
            for seat_pitch in [0.75, 0.85, 1.0, 1.5]:
                for num_aisles in [1, 2]:
                    usable_length = length * (1 - overhead_fraction)
                    rows = int(usable_length / seat_pitch)
                    usable_width = width - (num_aisles * aisle_width)
                    seats_per_row = int(usable_width / seat_width)
                    total_passengers = rows * seats_per_row

                    if total_passengers >= min_passengers:
                        results.append({
                            "length_m": length,
                            "width_m": width,
                            "seat_pitch_m": seat_pitch,
                            "num_aisles": num_aisles,
                            "rows": rows,
                            "seats_per_row": seats_per_row,
                            "total_passengers": total_passengers
                        })

    # Find the most efficient (smallest plane that works)
    results.sort(key=lambda x: (x["total_passengers"], x["length_m"], x["width_m"]))
    return results[:5]

