import random

def roll_dice():
    """Simulate rolling three 6-sided dice and return the sum."""
    dice1 = random.randint(1, 6)
    dice2 = random.randint(1, 6)
    dice3 = random.randint(1, 6)
    return dice1 + dice2 + dice3

def calculate_points(total):
    """Calculate points based on the sum of three dice."""
    if 3 <= total <= 10:
        return 0
    elif 11 <= total <= 16:
        return 10
    elif 17 <= total <= 22:
        return 20
    elif 23 <= total <= 28:
        return 30
    elif 29 <= total <= 34:
        return 40
    elif 35 <= total <= 40:
        return 50

def play_game(num_players):
    """Simulate a board game for a given number of players."""
    scores = {}

    for player in range(1, num_players + 1):
        total = roll_dice()
        points = calculate_points(total)
        scores[f"Player {player}"] = {"Dice Sum": total, "Points": points}
        print(f"Player {player} rolled a sum of {total} and gets {points} points.")

    winner = max(scores, key=lambda x: scores[x]["Points"])
    print(f"\nThe winner is {winner} with {scores[winner]['Points']} points!")
    return scores

